"""Managed-key regressions; all credentials here are public test fixtures."""
import base64
import os
import sqlite3

import pytest
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

from src.core.onyx_client import OnyxClientError, resolve_api_key
from src.core.onyx_db import init_onyx_tables
from src.core.onyx_tenant_service import OnyxTenantService

MASTER = bytes.fromhex('33' * 32)
REFERENCE = 'ONYX_API_KEY_HOTEL_1'
# Generated by the Node vault, not by the Python implementation under test.
NODE_VECTOR = 'v2.4gFkH-EoiYnLQCrP.xzFwtAA8Ke--cFkzhNpiBA.9ZMe01OixbOe-S-tbEpkhHVSQDQB5EAhgcTBEQwGQJc'


@pytest.fixture
def database(tmp_path, monkeypatch):
    path = tmp_path / 'credentials.db'
    monkeypatch.setenv('ONYX_CREDENTIALS_MASTER_KEY', MASTER.hex())
    monkeypatch.setenv('DB_PATH', str(path))
    with sqlite3.connect(path) as conn:
        conn.execute('CREATE TABLE instances(id INTEGER PRIMARY KEY,name TEXT,isActive INTEGER DEFAULT 1)')
        conn.execute("INSERT INTO instances(id,name) VALUES (1,'One'),(2,'Two')")
        init_onyx_tables(conn)
    return path


def save(path, ciphertext=NODE_VECTOR):
    with sqlite3.connect(path) as conn:
        conn.execute("INSERT INTO onyx_tenant_credentials(env_ref,business_id,token_encrypted) VALUES (?,1,?) "
                     "ON CONFLICT(env_ref) DO UPDATE SET token_encrypted=excluded.token_encrypted,revision=revision+1", (REFERENCE,ciphertext))


def seal(value):
    iv = os.urandom(12)
    encrypted = AESGCM(MASTER).encrypt(iv, value.encode(), f'ava:onyx:1:{REFERENCE}:v2'.encode())
    encode = lambda data: base64.urlsafe_b64encode(data).decode().rstrip('=')
    return '.'.join(('v2',encode(iv),encode(encrypted[-16:]),encode(encrypted[:-16])))


def test_node_ciphertext_resolves_without_caching_in_environment(database, monkeypatch):
    save(database)
    monkeypatch.delenv(REFERENCE, raising=False)
    assert resolve_api_key(REFERENCE) == 'public-cross-runtime-test-vector'
    assert REFERENCE not in os.environ


def test_rotation_and_revocation_override_a_stale_environment_value(database, monkeypatch):
    save(database)
    monkeypatch.setenv(REFERENCE, 'stale-cached-value')
    assert resolve_api_key(REFERENCE) == 'public-cross-runtime-test-vector'
    save(database,seal('rotated-fixture'))
    assert resolve_api_key(REFERENCE) == 'rotated-fixture'
    with sqlite3.connect(database) as conn:
        conn.execute('UPDATE onyx_tenant_credentials SET enabled=0')
    with pytest.raises(OnyxClientError,match='cannot be resolved'):
        resolve_api_key(REFERENCE)
    with sqlite3.connect(database) as conn:
        conn.execute('DELETE FROM onyx_tenant_credentials')
    with pytest.raises(OnyxClientError):
        resolve_api_key(REFERENCE)


def test_swapped_tenant_ciphertext_fails_closed(database):
    save(database)
    with sqlite3.connect(database) as conn:
        conn.execute("INSERT INTO onyx_tenant_credentials(env_ref,business_id,token_encrypted) VALUES ('ONYX_API_KEY_HOTEL_2',2,?)", (NODE_VECTOR,))
    with pytest.raises(OnyxClientError) as error:
        resolve_api_key('ONYX_API_KEY_HOTEL_2')
    assert error.value.code == 'ONYX_CREDENTIALS_INVALID'


def test_missing_or_wrong_master_key_does_not_fall_back_to_env(database, monkeypatch):
    save(database)
    monkeypatch.setenv(REFERENCE, 'stale-cached-value')
    for key in ('', '44'*32):
        monkeypatch.setenv('ONYX_CREDENTIALS_MASTER_KEY', key)
        with pytest.raises(OnyxClientError):
            resolve_api_key(REFERENCE)


def test_disable_revokes_managed_key_and_public_status(database):
    save(database)
    service = OnyxTenantService(str(database))
    service.configure(1, {'base_url':'https://onyx.example.test/api','credential_ref':REFERENCE,'cc_pair_id':42})
    assert service.public(1)['credential_available'] is True
    service.disable(1)
    assert service.public(1)['credential_available'] is False
    with pytest.raises(OnyxClientError):
        resolve_api_key(REFERENCE)


def test_configuration_rejects_another_hotels_managed_reference(database):
    service = OnyxTenantService(str(database))
    with pytest.raises(ValueError,match='another business'):
        service.configure(2,{'base_url':'https://onyx.example.test/api','credential_ref':REFERENCE,'cc_pair_id':42})


@pytest.mark.parametrize('token', ['sk-onyx-tenant-1-fake','native-legacy-test-fixture'])
def test_legacy_table_migration_has_no_plaintext_token(database,token):
    with sqlite3.connect(database) as conn:
        conn.execute('DROP TABLE onyx_tenant_credentials')
        conn.execute('CREATE TABLE onyx_tenant_credentials(env_ref TEXT PRIMARY KEY,token TEXT NOT NULL,business_id INTEGER NOT NULL)')
        conn.execute('INSERT INTO onyx_tenant_credentials VALUES (?,?,1)',(REFERENCE,token))
        init_onyx_tables(conn)
        row = conn.execute('SELECT token,token_encrypted,enabled FROM onyx_tenant_credentials').fetchone()
        assert row[0] == ''
        if token.startswith('sk-onyx-tenant-'):
            assert row[2] == 0
        else:
            assert token not in row[1]
    if not token.startswith('sk-onyx-tenant-'):
        assert resolve_api_key(REFERENCE) == token


def test_missing_database_is_not_created_by_credential_lookup(tmp_path,monkeypatch):
    path = tmp_path/'absent.db'
    monkeypatch.setenv('DB_PATH',str(path))
    with pytest.raises(OnyxClientError):
        resolve_api_key(REFERENCE)
    assert not path.exists()
